<h1>Quick Entry from Broker</h1><p>Paste the broker's multiline trade detail to parse asset, direction, dates, quantity, prices, P&amp;L, fee and ticket. The result can be copied into the Trades form.</p><div class="card"><textarea id="broker" rows="14" placeholder="BTC/USD\nsell\n01 Jul 09:14:59\n01 Jul 09:22:58\n0.01\n106,811.43\n106,794.8\n+0.16\nPosition ID\n1590998273\nCommission, USD\n-0.16"></textarea><p><button type="button" id="parse">Parse Data</button></p><div id="result"></div></div><script nonce="<?=e(csp_nonce())?>">(function(){const text=document.getElementById('broker'),out=document.getElementById('result');function parse(){const l=text.value.trim().split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(l.length<8){out.innerHTML='<p class="error">Expected at least 8 lines.</p>';return}const asset=l[0].replace(/\/USD|\/USDT|\/.*/i,'').toUpperCase(),side=/sell/i.test(l[1])?'Short':'Long',num=x=>parseFloat(String(x).replace(/,/g,'')),ticket=(l.slice(8).find(x=>/^\d+$/.test(x))||''),feeLine=l.slice(8).join(' '),fm=feeLine.match(/-(\d+(?:\.\d+)?)/),fee=fm?num(fm[1]):0;const html='<div class="card"><h2>Parsed</h2><p><strong>Asset:</strong> '+asset+' · <strong>Side:</strong> '+side+'</p><p><strong>Open:</strong> '+l[2]+' · <strong>Close:</strong> '+l[3]+'</p><p><strong>Quantity:</strong> '+num(l[4])+' · <strong>Entry:</strong> '+num(l[5])+' · <strong>Exit:</strong> '+num(l[6])+'</p><p><strong>P&amp;L:</strong> '+num((l[7]||'').match(/[+-]?(\d+(?:\.\d+)?)/)?.[0]||0)+' · <strong>Fee:</strong> '+fee+' · <strong>Ticket:</strong> '+ticket+'</p><p><a href="/trades">Open Trades and enter these values</a></p></div>';out.innerHTML=html}document.getElementById('parse').addEventListener('click',parse)})();</script>
